// Find the Images widget (right-column) and Video carousel (left-column)
var images = document.querySelector('[data-fast-name="images"]');
var video = document.querySelector('[data-fast-name="video-unisearch"]');

// Find the first real organic result (first serp-item that is not video/images)
var firstItem = element.querySelector('.serp-item[data-cid="0"]');

if (!images || !video || !firstItem) return;

// Mark elements so we don't re-insert repeatedly (idempotency guard)
if (images.dataset.movedToTop === '1' && video.dataset.movedToTop === '1') return;

// Style the images widget to fit in the left column flow
images.style.width = '100%';
images.style.marginBottom = '16px';
images.dataset.movedToTop = '1';
video.dataset.movedToTop = '1';

// Insert Images first (will appear at top), then Video below it
element.insertBefore(images, firstItem);
element.insertBefore(video, firstItem);
